def _column_to_pylist(column) -> list:
    """Convert a pyarrow Array/ChunkedArray to a Python list.

    For primitive types without nulls, ``.to_numpy().tolist()`` is much faster
    than ``.to_pylist()`` (often >20x for floats and ints), and produces
    semantically identical native Python objects.
    """
    if column.null_count == 0:
        col_type = column.type
        if (
            pa.types.is_integer(col_type)
            or pa.types.is_floating(col_type)
            or pa.types.is_boolean(col_type)
            or pa.types.is_string(col_type)
            or pa.types.is_large_string(col_type)
        ):
            return column.to_numpy(zero_copy_only=False).tolist()
    return column.to_pylist()


